  const existing = await User.findOne({ email: normalizedEmail });
  if (existing) {
    const legacyKyc = {
      verified: "approved",
      failed: "rejected",
      unverified: "pending"
    };
    if (legacyKyc[existing.kycStatus]) {
      existing.kycStatus = legacyKyc[existing.kycStatus];
    }
    let needsSave = existing.isModified();
    if (existing.role !== "admin") {
      existing.role = "admin";
      existing.status = "active";
      needsSave = true;
    }
    if (existing.subscriptionStatus !== "active") {
      existing.subscriptionStatus = "active";
      needsSave = true;
    }
    if (needsSave) await existing.save();
    return;
  }
  await User.create({
    firstName: firstName || "Site",
    lastName: lastName || "Admin",
    email: normalizedEmail,
    password,
    role: "admin",
    status: "active",
    plan: "Ultra",
    subscriptionStatus: "active",
    kycStatus: "approved",
    isEmailVerified: true
  });
