    grossMonthlyRent,
    mortgageMonthly,
    managementMonthly,
    insuranceMaintenanceMonthly,
    sellerDescription: listing.description || options.description || "No description provided.",
    comparableRange: formatGbpRange(comparableLow, comparableHigh),
